using SchoolERP.Domain.Entities;
using SchoolERP.Domain.Enums;
using SchoolERP.Infrastructure.Identity;
namespace SchoolERP.UnitTests.TestCommon.Builders;
public sealed class TenantBuilder{private string _name="Contoso Tenant",_slug="contoso";public TenantBuilder WithName(string x){_name=x;return this;}public TenantBuilder WithSlug(string x){_slug=x;return this;}public Tenant Build()=>Tenant.Create(_name,_slug,occurredOnUtc:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class SchoolBuilder{private Guid _tenant=TestIds.TenantA;private string _name=TestData.SchoolName,_code="CPS";public SchoolBuilder WithTenant(Guid x){_tenant=x;return this;}public SchoolBuilder WithCode(string x){_code=x;return this;}public School Build()=>School.Create(_tenant,_name,_code,occurredOnUtc:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class CampusBuilder{private Guid _tenant=TestIds.TenantA,_school=TestIds.SchoolA;private bool _main;public CampusBuilder AsMain(){_main=true;return this;}public Campus Build()=>Campus.Create(_tenant,_school,"Main Campus","MAIN",_main,occurredOnUtc:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class AcademicYearBuilder{private DateOnly _start=new(2026,4,1),_end=new(2027,3,31);public AcademicYearBuilder WithDates(DateOnly s,DateOnly e){_start=s;_end=e;return this;}public AcademicYear Build()=>AcademicYear.Create(TestIds.TenantA,TestIds.SchoolA,"2026-2027","AY2627",_start,_end,occurredOnUtc:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class SchoolClassBuilder{public SchoolClass Build()=>SchoolClass.Create(TestIds.TenantA,TestIds.SchoolA,TestIds.AcademicYearA,"Grade 6","G6",1,now:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class ClassSectionBuilder{private int? _capacity=40;public ClassSectionBuilder WithCapacity(int? x){_capacity=x;return this;}public ClassSection Build()=>ClassSection.Create(TestIds.TenantA,TestIds.SchoolA,TestIds.AcademicYearA,TestIds.ClassA,"Section A","A",1,_capacity,now:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class SubjectBuilder{public Subject Build()=>Subject.Create(TestIds.TenantA,TestIds.SchoolA,TestIds.AcademicYearA,"Mathematics","MATH",SubjectType.Core,1,now:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class DepartmentBuilder{public Department Build()=>Department.Create(TestIds.TenantA,TestIds.SchoolA,null,"Science","SCI",DepartmentType.Academic,1,now:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class HouseBuilder{private string _color="#10B981";public HouseBuilder WithColor(string x){_color=x;return this;}public House Build()=>House.Create(TestIds.TenantA,TestIds.SchoolA,"Emerald","EMR",null,_color,1,now:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class CalendarEventBuilder{public SchoolCalendarEvent Build()=>SchoolCalendarEvent.Create(TestIds.TenantA,TestIds.SchoolA,null,TestIds.AcademicYearA,"Founders Day","FOUNDERS",SchoolCalendarEventType.SchoolEvent,new(2026,9,15),new(2026,9,15),true,null,null,false,"#EF4444",null,null,now:new TestClock().GetUtcNow().UtcDateTime);}
public sealed class UserBuilder{public ApplicationUser Build()=>ApplicationUser.Create("Test","Admin",TestData.Email,TestIds.TenantA,TestIds.SchoolA,TestIds.CampusA,true);}
public sealed class RoleBuilder{public ApplicationRole Build()=>ApplicationRole.CreateTenant(TestIds.TenantA,"AUDITOR","Auditor",RoleType.School);}
